import pandas as pd
from datetime import datetime, timedelta

def format(path):
    # Read the CSV file
    df = pd.read_csv(path)

    # Assuming the 4th column (index 3) contains time values
    # Adjust the column index if needed
    time_column_index = 3

    # Function to subtract 3 hours from a time value
    def subtract_three_hours(time_str):
        try:
            # Handle different time formats
            if ':' in time_str:
                time_obj = datetime.strptime(time_str, '%H:%M:%S')
            else:
                time_obj = datetime.strptime(time_str, '%H:%M')

            # Subtract 3 hours
