import csv
import pandas as pd
from datetime import datetime, timedelta
import sys
import os

def format_file(input_path):
    # Check if file exists
    if not os.path.exists(input_path):
        print(f"Error: File {input_path} not found")
        return

    # Read the CSV file
    df = pd.read_csv(input_path)

    # Assuming the 4th column (index 3) contains time values
    # Adjust the column index if needed
    time_column_index = 3

    # Function to subtract 3 hours from a time value
    def subtract_three_hours(time_str):
        try:
            # Convert to string if not already
            time_str = str(time_str).strip()

            # Handle different time formats
            if ':' in time_str:
                # Try different time formats
                try:
                    time_obj = datetime.strptime(time_str, '%H:%M:%S')
                except ValueError:
                    time_obj = datetime.strptime(time_str, '%H:%M')
            else:
                # Assume format like 'HHMM' or just 'HH'
                if len(time_str) == 4:
                    time_obj = datetime.strptime(time_str, '%H%M')
                elif len(time_str) <= 2:
                    time_obj = datetime.strptime(time_str, '%H')
                else:
                    return time_str

            # Subtract 3 hours
            adjusted_time = time_obj - timedelta(hours=3)

            # Return in a consistent format
            return adjusted_time.strftime('%H:%M:%S')
        except ValueError:
            # If parsing fails, return the original value
            return time_str

    # Apply the function to the 4th column
    df.iloc[:, time_column_index] = df.iloc[:, time_column_index].apply(subtract_three_hours)

    # Write to Excel file
    output_path = '/tmp/audit-export.xlsx'
    df.to_excel(output_path, index=False)
    print(f"Adjusted data written to {output_path}")

if __name__ == '__main__':
    if len(sys.argv) > 1:
        format_file(sys.argv[1])
    else:
        print("Please provide a CSV file path as an argument")
